import React from 'react';

function MegaboxGuide() {
  // 💡 [데이터 구조] public 폴더가 최상단에 있을 때 가장 안전한 상대/정적 경로 형식 적용
  const guideList = [
    {
      id: 1,
      title: "Dolby Cinema",
      badge: "",
      normalImage: "img/01/01.png",
      hoverImage: "img/01/01.png"
    },
    {
      id: 2,
      title: "Dolby Vision Atmos",
      badge: "NEW",
      normalImage: "img/01/02.png",
      hoverImage: "img/01/02.png"
    },
    {
      id: 3,
      title: "Mega MX4D",
      badge: "",
      normalImage: "img/01/03.png",
      hoverImage: "img/01/03.png"
    },
    {
      id: 4,
      title: "Mega Dolby Atmos",
      badge: "",
      normalImage: "img/01/04.png",
      hoverImage: "img/01/04.png"
    },
    {
      id: 5,
      title: "Mega LED",
      badge: "NEW",
      normalImage: "img/01/05.png",
      hoverImage: "img/01/05.png"
    },
    {
      id: 6,
      title: "Boutique Private",
      badge: "",
      normalImage: "img/01/06.png",
      hoverImage: "img/01/06.png"
    }
  ];

  return (
    <section className="w-full bg-[#fbfbfa] pt-16 pb-16 flex flex-col items-center relative overflow-hidden">
      
      <div className="w-full max-w-6xl px-6">
        
        {/* 상단 타이틀 */}
        <div className="mb-8">
          <h2 className="text-2xl font-black text-zinc-900 tracking-tight">메가박스 안내</h2>
        </div>

        {/* 안내 카드 슬라이더/그리드 영역 */}
        <div className="relative flex items-center">
          
          {/* 좌측 슬라이드 화살표 버튼 */}
          <button className="absolute -left-5 z-10 w-10 h-10 rounded-full bg-white shadow-md border border-zinc-200 flex items-center justify-center text-zinc-400 hover:text-zinc-800 transition">
            &lt;
          </button>

          {/* 카드 목록 컨테이너 (170x170 정사각형 규격 적용) */}
          <div className="w-full grid grid-cols-2 md:grid-cols-6 gap-4">
            {guideList.map((item) => (
              <div 
                key={item.id} 
                className="group relative aspect-square rounded-2xl overflow-hidden shadow-lg bg-zinc-900 cursor-pointer border border-zinc-800 flex flex-col justify-end p-4 transition-all duration-300"
              >
                {/* 이미지 전환 컨테이너 */}
                <div className="absolute inset-0 w-full h-full bg-zinc-900 flex items-center justify-center overflow-hidden">
                  
                  {/* 1. 커서 올리기 전 이미지 */}
                  {item.normalImage ? (
                    <img 
                      src={item.normalImage} 
                      alt={item.title} 
                      className="absolute inset-0 w-full h-full object-cover transition-opacity duration-500 group-hover:opacity-0" 
                    />
                  ) : (
                    <div className="absolute inset-0 flex items-center justify-center group-hover:opacity-0 transition-opacity duration-500 p-2 text-center">
                      <span className="text-[10px] text-zinc-500">이미지 없음</span>
                    </div>
                  )}

                  {/* 2. 커서 올린 후 이미지 */}
                  {item.hoverImage ? (
                    <img 
                      src={item.hoverImage} 
                      alt={`${item.title} hover`} 
                      className="absolute inset-0 w-full h-full object-cover opacity-0 group-hover:opacity-100 group-hover:scale-105 transition-all duration-500" 
                    />
                  ) : (
                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-500 p-2 text-center bg-zinc-800">
                      <span className="text-[10px] text-zinc-300">호버 이미지 없음</span>
                    </div>
                  )}

                </div>

                {/* 어두운 그라데이션 오버레이 (텍스트 가독성 확보) */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent pointer-events-none z-10"></div>

                {/* 우측 상단 NEW 뱃지 */}
                {item.badge && (
                  <span className="absolute top-3 right-3 bg-[#00a086] text-white text-[9px] font-bold px-2 py-0.5 rounded shadow z-20">
                    {item.badge}
                  </span>
                )}

                {/* 하단 타이틀 텍스트 */}
                <div className="relative z-20">
                  <h4 className="text-xs font-bold text-white tracking-wide group-hover:text-purple-300 transition-colors">
                    {item.title}
                  </h4>
                </div>

              </div>
            ))}
          </div>

          {/* 우측 슬라이드 화살표 버튼 */}
          <button className="absolute -right-5 z-10 w-10 h-10 rounded-full bg-white shadow-md border border-zinc-200 flex items-center justify-center text-zinc-400 hover:text-zinc-800 transition">
            &gt;
          </button>

        </div>

      </div>

    </section>
  );
}

export default MegaboxGuide;
